#include <cstdio>
#include <cstdlib>
#include <vector>

int main(int argc, char **argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s N\n", argv[0]);
        return 1;
    }
    long long n = std::atoll(argv[1]);
    if (n < 0) {
        std::fprintf(stderr, "N must be non-negative\n");
        return 1;
    }
    const unsigned long long BASE = 1000000000ULL;
    std::vector<unsigned long long> a(1, 1), b(1, 1);
    for (long long i = 0; i < n; ++i) {
        std::vector<unsigned long long> c(b.size() > a.size() ? b.size() : a.size());
        unsigned long long carry = 0;
        for (size_t j = 0; j < c.size(); ++j) {
            unsigned long long s = carry;
            if (j < a.size()) s += a[j];
            if (j < b.size()) s += b[j];
            c[j] = s % BASE;
            carry = s / BASE;
        }
        if (carry) c.push_back(carry);
        a.swap(b);
        b.swap(c);
    }
    std::printf("%llu", a.back());
    for (size_t j = a.size() - 1; j-- > 0;) std::printf("%09llu", a[j]);
    std::printf("\n");
    return 0;
}
